pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        vm.prank(address(1));
        // proxiableUUID is external view notDelegated, we call it directly on c (which is a proxy after setup)
        bytes32 uuid = c.proxiableUUID();
        assertTrue(uuid == 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address delegator;

    function setUp() public {
        c = new C();
        delegator = address(new Delegator(c));
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != delegator);
        vm.assume(actor.code.length == 0);

        bytes memory directCall = abi.encodeWithSignature("proxiableUUID()");

        vm.prank(actor);
        (bool ok, bytes memory ret) = address(c).call(directCall);
        assertTrue(ok);
        bytes32 directResult = abi.decode(ret, (bytes32));

        bytes memory unverifiableBytes = bytes32(uint256(1));
        (bool dgOk, bytes memory dgRet) =
            delegator.call(abi.encodeWithSignature("callDelegate(bytes)", unverifiableBytes));
        assertTrue(dgOk);
        bytes32 delegateResult = abi.decode(dgRet, (bytes32));

        assertTrue(delegateResult == directResult);
    }
}

contract Delegator {
    C public immutable inner;
    constructor(C _inner) {
        inner = _inner;
    }
    function callDelegate(bytes calldata junk) external returns (bytes32) {
        bytes memory ret = address(inner).delegatecall(abi.encodeWithSignature("proxiableUUID()"));
        return abi.decode(ret, (bytes32));
    }
}

