// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(c));
        vm.assume(caller != address(0));
        Delegator delegator = new Delegator();
        vm.etch(caller, address(delegator).code);
        bytes memory data = abi.encodeWithSelector(c.proxiableUUID.selector);
        (bool ok, bytes memory result) = caller.call(abi.encodeWithSelector(Delegator.delegate.selector, address(c), data));
        assertTrue(ok && keccak256(abi.encodePacked(result)) == keccak256(abi.encodePacked(bytes32(0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc))));
    }
}

contract Delegator {
    function delegate(address target, bytes memory data) external returns (bytes memory) {
        (bool ok, bytes memory result) = target.delegatecall(data);
        require(ok, "delegatecall failed");
        return result;
    }
}

