pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ProxyHelper {
    address public target;
    bytes32 public fallbackReturn;
    constructor(address _target, bytes32 _fallbackReturn) {
        target = _target;
        fallbackReturn = _fallbackReturn;
    }
    fallback() external payable returns (bytes32) {
        return fallbackReturn;
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 maliciousReturn) public {
        vm.assume(maliciousReturn != 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc);
        ProxyHelper proxy = new ProxyHelper(address(c), maliciousReturn);
        (bool success, bytes memory data) = address(proxy).call(abi.encodeWithSignature("proxiableUUID()"));
        assertTrue(!success || abi.decode(data, (bytes32)) == 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc);
    }
}

