pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 returnSlot) public {
        ProxyHelper helper = new ProxyHelper();
        bytes32 result = helper.getProxiableUUID(address(c), returnSlot);
        assertTrue(result == 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc);
    }
}

contract ProxyHelper {
    bytes32 public slot;
    function getProxiableUUID(address target, bytes32 _slot) external returns (bytes32) {
        slot = _slot;
        (bool success, bytes memory data) = target.delegatecall(abi.encodeWithSignature("proxiableUUID()"));
        if (success) {
            return abi.decode(data, (bytes32));
        } else {
            revert("delegatecall failed");
        }
    }
    fallback() external payable returns (bytes32) {
        return slot;
    }
}

