pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract MaliciousAdmin {
    C public target;

    constructor(C _target) {
        target = _target;
    }

    function executeUpgrade(address newImpl, bytes memory data) external {
        target.upgradeToAndCall(newImpl, data);
    }
}

contract NewImpl is C {
    function fakeInit() public {}
}

contract InvMutTest is Test {
    C c;
    NewImpl newImpl;
    MaliciousAdmin admin;

    function setUp() public {
        c = new C();
        newImpl = new NewImpl();
        admin = new MaliciousAdmin(c);
    }

    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));
        vm.assume(accessControl.code.length == 0);

        // Give accessControl the necessary access for upgrade authorization
        bytes4 upgradeSelector = bytes4(0);
        bytes32 roleId = keccak256(abi.encodePacked(upgradeSelector, address(c)));

        // Simulate granting upgrade access to 'admin' for the upgrade selector
        // Since IAccessControl is not mockable without vm.mockCall, we use a custom deploy to bypass access check for upgrade.
        // The issue is that __UUPSUpgradeable_init() wasn't called, so upgradeToAndCall will fail due to internal state.

        // Initialize properly
        c.initialize(accessControl);

        // Attempt upgrade as admin
        vm.startPrank(address(admin));
        bool success;
        try c.upgradeToAndCall(address(newImpl), "") {
            success = true;
        } catch {
            success = false;
        }
        vm.stopPrank();

        assertTrue(success);
    }
}

