pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address validImpl) public {
        // Only test addresses that have code (candidate implementations)
        vm.assume(validImpl.code.length > 0);

        // Deploy a minimal access control that grants all access
        AccessControlMock ac = new AccessControlMock();
        // Initialize the contract under test with the access control
        c.initialize(address(ac));

        // Try to upgrade to the valid implementation via the proxy (we are the proxy, so the call is from this test contract,
        // which is the proxy itself). Since the test contract is the proxy, we impersonate the proxy with the upgrade call.
        bool ok = true;
        try c.upgradeToAndCall(validImpl, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: upgrade succeeds (ok == true). Buggy: upgrade reverts (ok == false) because UUPS init wasn't completed.
        assertTrue(ok, "Upgrade should succeed after proper initialization");
    }
}

// Minimal access control that always grants access to everyone for every selector
contract AccessControlMock {
    function initialize(address) external {}
    function checkAccess(bytes4, address, address) external view returns (bool) {
        return true;
    }
    function role(bytes4, address) external pure returns (bytes32) {
        return bytes32(0);
    }
}

