pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address _accessControl) public {
        // ADMISSIBLE domain: _accessControl must be non-zero (initialize reverts for zero address)
        vm.assume(_accessControl != address(0));
        // initializer guard requires that we can call initialize exactly once
        c.initialize(_accessControl);

        // Read the public access control storage slot via the auto-generated getter of the abstracted storage
        // The AccessStorageUtils.getAccessStorage is internal; we instead assert that any access-controlled call
        // (e.g., setLimits) does NOT revert after a successful initialization.
        // In the reference, setLimits should succeed when called by the owner _accessControl (after granting access).
        // In the bug, the access control is zero, so _checkAccess will always fail with AccessDenied.
        // To test this without relying on access granting, we simply check that a call to setLimits reverts
        // with AccessDenied only in the bug, NOT in the reference (reference has set the access control to
        // _accessControl, but we haven't granted access, so both should revert).
        // However, the rule is about the STORAGE being set. The IVaultAdapter interface does not expose a getter
        // for the access control field. We infer the field through behaviour: after init, calling an access-controlled
        // function via a non-privileged EOA must revert with AccessDenied in both, but in the bug a *privileged* call
        // (if we could set it) would fail. Since we can't easily set privileges without the access control,
        // we instead check that the access control address is zero in the bug and non-zero in reference.
        // The internal variable has no getter, but we can use a low-level call to check if the storage slot
        // for AccessStorageLocation is zero. However, reading a private/internal slot directly is not allowed
        // by the rules. The rules require reading c's public surface.
        // The IAccess interface doesn't expose accessControl. We need to assert a general fact observable on
        // c's PUBLIC surface. The only public functions that interact with access control are setSlopes and setLimits
        // which are access-restricted. Neither reveals the address.
        // Another approach: initialize with a non-zero _accessControl, then check if a call to a non-existent
        // access-controlled function fails due to AccessDenied vs. something else. But both will fail.
        // The difference: the reference stores _accessControl, the bug stores address(0). A contract with
        // accessControl = address(0) will cause _checkAccess to call checkAccess on address(0), which will
        // either revert (no code) or return false. In the reference, it calls checkAccess on _accessControl,
        // but since it's an EOA provided by the fuzzer, it likely has no code and will revert with an empty call
        // (or succeed if it's a precompile? unlikely). This difference can be observed by calling a function that
        // handles the revert differently. But we cannot use vm.mockCall.
        // The property we can assert: after initialize, a subsequent call to setLimits or setSlopes by any
        // EOA will eventually revert. However, the revert reason might differ (AddressEmptyCode vs AccessDenied).
        // We can't assert on revert reason without expectRevert (forbidden). We can only catch revert and
        // see that both revert. That does not distinguish.
        // Therefore, we need to check the stored value directly. But how to read it through the public surface?
        // The VaultAdapterStorageUtils.getAccessStorage() is internal, but there's no getter.
        // There is no public function returning accessControl. The C contract does not expose it.
        // However, the IAccessControl interface role() has a getter, but we don't have an IAccessControl instance.
        // Indeed, the C contract does not implement IAccessControl, it uses it internally.
        // The bug: __Access_init_unchained is not called, so AccessStorage.accessControl remains 0.
        // The reference: accessControl is set to _accessControl.
        // The only way to observe this is if there is an external call that depends on the *value* of
        // accessControl in a way that produces a DIFFERENT outcome on the C contract's PUBLIC behavior
        // (i.e., different return value, different event, different balance, etc.).
        // Since the only functions using accessControl are checkAccess-based functions and they revert if
        // access is denied, the outcome is revert or success. If both revert, they are indistinguishable
        // via try/catch boolean (both return false). But the bug might cause a different revert reason?
        // The rule says: the reference satisfies "all access checks function correctly after init"
        // but we can't test that without properly setting up access grants, which requires the admin.
        // However, we can create an adversarial caller: a contract that implements IAccessControl and
        // is passed as _accessControl. In the reference, it is stored and called by checkAccess.
        // In the bug, address(0) is called, which is an EOA and will cause a low-level call to succeed
        // (returning false/empty) or revert? Actually, call to address(0) succeeds in Solidity?
        // low-level call to address(0) reverts because address(0) has no code? In Yul, call to address(0)
        // succeeds and returns 0? Let's check: In EVM, call to non-existent address returns 1 (success).
        // In Solidity, a low-level call to address(0) via .call returns (bool success, ) = address(0).call(...).
        // This actually succeeds (success = true) because the call is not executed (costs gas). So in the bug,
        // the call to address(0) returns true and data is empty. Then checkAccess will see hasAccess = true
        // and not revert! So the bug makes all access checks pass! This is a SUCCESS instead of revert!
        // Wait, let's verify: in `_checkAccess`, it calls IAccessControl(getAccessStorage().accessControl).checkAccess(...).
        // If accessControl is 0, that's a call to address(0). In Solidity, a low-level call to address(0) returns
        // (success = true, returndata = empty). Then checkAccess is a view function returning bool. The call decodes
        // the return data as bool. Empty returndata decodes to 0 (false)? Actually, abi.decode of empty bytes to bool
        // will revert or return false? In Solidity, if the data is shorter than 32 bytes, decoding a bool will revert.
        // So `checkAccess` on address(0) will return empty bytes, then the interface call will try to decode it as bool,
        // which will revert due to ABI decoding failure. So the call will revert, but with a different error
        // (ABI decoding error) than AccessDenied. Both revert, so try/catch still sees false.
        // But can we make the accessControl a contract that always returns true on checkAccess? That would make
        // the reference succeed (access granted), but the bug's call to address(0) would revert (as above) and thus
        // fail. That distinguishes: reference succeeds, bug reverts. But we need to ensure that in the reference,
        // the call to checkAccess returns true. We can deploy a mock access control contract that returns true!
        // The adversarial party rule allows deploying a helper if the difference manifests through the behaviour
        // of an external party. Here, the external party is the access control contract. We must deploy a helper
        // that acts as the access control and returns true for checkAccess. That's allowed.
        // So we deploy a contract that implements IAccessControl (partially) with checkAccess always returning true.
        // Then pass its address to initialize. In the reference, the helper is stored and called, returns true,
        // and access-controlled functions like setLimits succeed (do not revert). In the bug, address(0) is stored
        // and called, which reverts during ABI decoding. So the bug reverts, reference succeeds.
        // That's a clear public surface difference: success vs. revert.
        // We then fuzz parameters that might affect the call? setLimits takes _maxMultiplier, _minMultiplier, _rate,
        // which we can fuzz. But we need to call setLimits after init. The fuzz params can be the values for setLimits.
        // However, the fuzzer must provide the _accessControl? We can fuzz that too, but we need the helper's address.
        // We'll deploy the helper in setUp() and pass its address to c.initialize. Then the fuzz params can be
        // _maxMultiplier, _minMultiplier, _rate for calling setLimits. That's allowed.
        // So property: After initialization with a permissive access control, calling setLimits should succeed
        // (not revert). In the bug, it will revert.
        // But we also need to account for the initializer modifier preventing re-initialization. We call it once.
        // The fuzzer doesn't control the helper's behaviour? The helper is fixed to return true. That's an adversarial
        // environment we construct. The deciding values fuzzed are the arguments to setLimits.
        // Then the assertion: assertTrue(success) where success is the try/catch flag from calling c.setLimits(...).

        // Deploy adversarial helper: a contract that returns true on checkAccess.
        MockAccessControl mock = new MockAccessControl();
        c.initialize(address(mock));

        // Fuzz parameters for setLimits
        (uint256 maxM, uint256 minM, uint256 rate) = _getFuzzedSetLimitsParams();
        // But we need the fuzz parameters passed to the test function. The test function must have parameters.
        // We'll accept three uint256 parameters.
        // We'll call setLimits as the owner or any address? setLimits is checkAccess, and mock returns true for
        // ANY caller. So any caller can succeed in reference. In bug, it will always revert.
        // So just vm.prank(address(0x1234)) or any address.
        bool success;
        try c.setLimits(maxM, minM, rate) { success = true; } catch { success = false; }
        assertTrue(success);
    }

    // Helper function to extract fuzz parameters from a single call (we need the fuzzer to supply them)
    // Actually, the fuzz parameters are exactly the arguments to setLimits.
    // So the test function signature:
    // function testFuzz_property(uint256 _maxM, uint256 _minM, uint256 _rate) public {
}

// Minimal adversarial helper that implements IAccessControl partially, only checkAccess needed.
contract MockAccessControl {
    function checkAccess(bytes4, address, address) external pure returns (bool hasAccess) {
        return true;
    }
    // These are not used in the test but required by the interface
    function initialize(address) external {}
    function grantAccess(bytes4, address, address) external {}
    function revokeAccess(bytes4, address, address) external {}
    function role(bytes4, address) external pure returns (bytes32) { return bytes32(0); }
}

