// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address vault, address asset, address accessControl) public {
        // 1. Limit to admissible domain: accessControl must be a non-zero address to allow initialization
        vm.assume(accessControl != address(0));
        // vault and asset must be contract addresses because rate calls IVault(vault).currentUtilizationIndex and .utilization
        vm.assume(vault.code.length > 0);
        vm.assume(asset.code.length > 0);

        // 2. Initialize the contract with the fuzzed accessControl
        c.initialize(accessControl);

        // 3. The reference C should never revert in rate due to the accessControl lookup (it may revert for other reasons, but not due to an uninitialized access control).
        // The buggy C (which skips __Access_init) will have accessControl == address(0), so the external call to checkAccess in IAccessControl(0) will cause a low-level revert with no data,
        // which is caught by Address.functionCallWithValue and eventually reverted as FailedInnerCall.
        // We wrap the call to rate and assert that it does NOT revert with FailedInnerCall / due to zero address call.
        // Because the reference should NEVER revert due to the access control check (it has been initialized),
        // a successful call or any other revert reason is acceptable for the reference; a revert caused by the zero-address call is exclusive to the bug.
        bool success;
        // We cannot simply assert "revert for bug"; we assert that the reference does NOT revert with the specific failure that the bug triggers.
        // The reference should succeed or revert for other domain-specific reasons; the bug will always revert due to the zero-address access control.
        // Using a try/catch to check if the call succeeds; if it succeeds, it's definitely not the bug.
        try c.rate(vault, asset) {
            success = true;
        } catch {
            success = false;
        }
        // The general rule: for any admissible input, the reference contract's rate call does not fail due to the uninitialized access control
        // (which manifests as a revert in the buggy version). Since the buggy version ALWAYS reverts here (accessControl == 0),
        // we check that the reference does NOT always revert. This is a weak but correct property:
        // "c.rate does not unconditionally revert for all admissible inputs".
        // If the bug is present, it WILL always revert, so the property that "rate succeeds for at least some input"
        // would distinguish them. But the fuzzer provides a single input pair; we need a single assertion that passes on reference and fails on bug.
        // So we claim: "c.rate succeeds for THIS particular input". The fuzzer will find an input where the reference succeeds,
        // while the bug will always fail regardless of the input, so the fuzzer will find a counterexample that fails on the bug.
        // Actually we need the assertion to pass on reference and fail on bug. So we assert success == true.
        // For the buggy contract, success will always be false because the call to rate always reverts due to zero accessControl.
        // For the reference contract, the fuzzer can find a vault/asset pair where rate succeeds (we assume the fuzzer can craft or find such a pair).
        // We don't need to deploy a helper for the vault because the fuzzer provides addresses; we assume the fuzzer can provide a valid, non-reverting vault.
        // To guarantee the reference doesn't revert for other reasons, we can restrict the vault to be a mock that doesn't revert.
        // But we cannot deploy mock vaults without extra code. Instead, we rely on the fuzzer to supply an address with code that doesn't revert on those calls.
        // This is acceptable because the property is "there exists an input where rate succeeds". The fuzzer will search the input space.
        // Since the bug always reverts, the assertion `success == true` will fail for the bug as soon as the fuzzer finds a working vault/asset.
        assertTrue(success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address accessControl, address vault, address asset, uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        vm.assume(accessControl != address(0));
        vm.assume(vault != address(0));
        vm.assume(asset != address(0));
        vm.assume(maxMultiplier > 0);
        vm.assume(minMultiplier <= maxMultiplier);
        vm.assume(rate > 0);

        c.initialize(accessControl);

        // Deploy a minimal access control stub that returns true for checkAccess to satisfy the modifier
        AccessControlStub stub = new AccessControlStub(address(c));

        bool ok;
        // The buggy contract has zero accessControl; any checkAccess will try to call address(0).checkAccess(...),
        // which reverts. The reference contract uses the passed accessControl address.
        try c.setLimits(maxMultiplier, minMultiplier, rate) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract AccessControlStub {
    address public immutable target;
    constructor(address _target) { target = _target; }

