        MockVault mockVault = new MockVault(elapsed, utilization, indexDiff);
        // Deploy minimal mock access control that grants access to all
        MockAccessControl mockAccess = new MockAccessControl();
        c.initialize(address(mockAccess));
        // Set slopes and limits so that _applySlopes runs deterministically
        vm.prank(address(mockAccess));
        c.setSlopes(address(0), IVaultAdapter.SlopeData(kink, slope0, slope1));
        vm.prank(address(mockAccess));
        c.setLimits(maxMultiplier, minMultiplier, rate);

        // Warp to a future timestamp so that elapsed != block.timestamp branch is taken
        vm.warp(elapsed);
        // First call to set stored index and lastUpdate
        vm.prank(address(mockAccess));
        c.rate(address(mockVault), address(0));

        // Warp again by elapsed so that elapsed == block.timestamp - lastUpdate and elapsed != block.timestamp
        vm.warp(2 * elapsed);
        // Second call will use the (index - utilizationData.index) / elapsed path
        vm.prank(address(mockAccess));
        uint256 rateP = c.rate(address(mockVault), address(0));

        // Compute expected rate with bug fix (no +1)
        uint256 correctUtilization = indexDiff / elapsed; // integer division
        uint256 correctRate = _computeRate(kink, slope0, slope1, minMultiplier, maxMultiplier, rate, correctUtilization, elapsed);

        assertTrue(rateP == correctRate);
    }

    function _computeRate(uint256 kink, uint256 slope0, uint256 slope1, uint256 minMultiplier, uint256 maxMultiplier, uint256 rate, uint256 utilization, uint256 elapsed) internal pure returns (uint256) {
        // Simulates _applySlopes logic without storage for a known initial multiplier of 1e27
        uint256 multiplier = 1e27;
        if (utilization > kink) {
            uint256 excess = utilization - kink;
            multiplier = multiplier * (1e27 + (1e27 * excess / (1e27 - kink)) * elapsed * rate / 1e27) / 1e27;
            if (multiplier > maxMultiplier) multiplier = maxMultiplier;
            return (slope0 + (slope1 * excess / 1e27)) * multiplier / 1e27;
        } else {
            multiplier = multiplier * 1e27 / (1e27 + (1e27 * (kink - utilization) / kink) * elapsed * rate / 1e27);
            if (multiplier < minMultiplier) multiplier = minMultiplier;
            return (slope0 * utilization / kink) * multiplier / 1e27;
        }
    }
}

contract MockVault {
    uint256 public elapsed;
    uint256 public utilizationValue;
    uint256 public indexDiff;
    constructor(uint256 _elapsed, uint256 _utilization, uint256 _indexDiff) {
        elapsed = _elapsed;
        utilizationValue = _utilization;
        indexDiff = _indexDiff;
    }
    function currentUtilizationIndex(address) external view returns (uint256) {
        return indexDiff + 1e27;
    }
    function utilization(address) external view returns (uint256) {
        return utilizationValue;
    }
}

contract MockAccessControl {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}
